<script setup>
import {ref} from 'vue';import {post,setCsrfToken} from '../api/client';
const emit=defineEmits(['authenticated']),mode=ref('login'),username=ref(''),password=ref(''),displayName=ref(''),email=ref(''),mobile=ref(''),error=ref(''),busy=ref(false);
function switchMode(value){mode.value=value;error.value=''}
async function submit(){error.value='';busy.value=true;try{const path=mode.value==='login'?'/auth/login':'/auth/register';const body=mode.value==='login'?{username:username.value,password:password.value}:{username:username.value,password:password.value,display_name:displayName.value,email:email.value||null,mobile:mobile.value||null};const value=await post(path,body);setCsrfToken(value.csrf_token);emit('authenticated',{...value.user,csrf_token:value.csrf_token})}catch(e){error.value=e.message}finally{busy.value=false}}
</script>
<template><div class="auth-page"><form class="auth-card card" @submit.prevent="submit"><div class="auth-brand"><b>Q</b><div><h1>量化观察台</h1><span>STOCK LAB</span></div></div><div class="model-tabs"><button type="button" :class="{active:mode==='login'}" @click="switchMode('login')">账号登录</button><button type="button" :class="{active:mode==='register'}" @click="switchMode('register')">注册账号</button></div><label v-if="mode==='register'">显示名称<input v-model="displayName" required maxlength="100"></label><label>用户名<input v-model="username" required minlength="3" maxlength="50" autocomplete="username" autofocus></label><label v-if="mode==='register'">邮箱（选填）<input v-model="email" type="email" autocomplete="email"></label><label v-if="mode==='register'">手机号（选填）<input v-model="mobile" autocomplete="tel"></label><label>密码<input v-model="password" type="password" required minlength="10" :autocomplete="mode==='login'?'current-password':'new-password'"></label><p v-if="mode==='register'" class="hint">密码至少 10 位并同时包含字母和数字。注册账号默认为只读用户。</p><p v-if="error" class="negative">{{error}}</p><button :disabled="busy">{{busy?'处理中…':mode==='login'?'登录':'注册并登录'}}</button></form></div></template>
